//! `java.nio.charset` encoders this crate carries because no Rust crate reproduces them: Java's EUC-JP (which, unlike
//! WHATWG's, writes JIS X 0212 as `0x8F` + two bytes) and Big5 (without HKSCS), built from Unicode's mapping
//! files plus Java's EUC-JP differences and checked against a JDK recording (`charset_data.rs`, generated by
//! `reference/gen_charsets.py`). The charsets whose Java and WHATWG mappings agree
//! are left to `encoding_rs`.

use crate::charset_data::{BIG5, BIG5_ALIASES, EUC_JP, EUC_JP_ALIASES};

/// A Java charset carried here.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Charset {
    name: &'static str,
    map: &'static [(u16, u32)],
}

impl Charset {
    /// `Charset.forName(name)` for the charsets carried here: the canonical name or an alias, case-insensitively;
    /// `None` for any other name.
    pub fn for_name(name: &str) -> Option<Charset> {
        let is = |canonical: &str, aliases: &[&str]| {
            name.eq_ignore_ascii_case(canonical) || aliases.iter().any(|a| name.eq_ignore_ascii_case(a))
        };
        if is("EUC-JP", &EUC_JP_ALIASES) {
            Some(Charset { name: "EUC-JP", map: &EUC_JP })
        } else if is("Big5", &BIG5_ALIASES) {
            Some(Charset { name: "Big5", map: &BIG5 })
        } else {
            None
        }
    }

    /// `name()`: the canonical name.
    pub fn name(&self) -> &'static str {
        self.name
    }

    /// `String.getBytes(charset)`: an unmappable char (every supplementary one included) becomes the replacement
    /// `?`.
    pub fn encode(&self, s: &str) -> Vec<u8> {
        let mut out = Vec::with_capacity(s.len());
        for c in s.chars() {
            match self.lookup(c as u32) {
                Some(b) => push(&mut out, b),
                None if c.is_ascii() => out.push(c as u8),
                None => out.push(b'?'),
            }
        }
        out
    }

    fn lookup(&self, cp: u32) -> Option<u32> {
        let cp = u16::try_from(cp).ok()?;
        self.map.binary_search_by(|e| e.0.cmp(&cp)).ok().map(|i| self.map[i].1)
    }
}

fn push(out: &mut Vec<u8>, b: u32) {
    let bytes = b.to_be_bytes();
    let skip = if b < 0x100 {
        3
    } else if b < 0x1_0000 {
        2
    } else {
        1
    };
    out.extend_from_slice(&bytes[skip..]);
}
